function topicReference(topic, catalog = []) {
  switch (topic) {
    case "fields":
      return { title: "\u6A21\u5757\u5B57\u6BB5\u901F\u67E5", text: fieldReference() };
    case "deps":
      return { title: "\u4F9D\u8D56\u7BAD\u5934\u4E0E API \u76F4\u8FDE", text: DEPS_REFERENCE };
    case "renders":
      return { title: "\u6E32\u67D3\u6570\u636E\u5B57\u6BB5", text: RENDERS_REFERENCE };
    case "flow":
      return { title: "\u4F34\u968F\u5F00\u53D1\u4E3B\u6D41\u7A0B", text: FLOW_REFERENCE };
    case "policy":
      return { title: "\u67B6\u6784\u89C4\u5219 policy.yml", text: policyReference() };
    case "errors":
      return { title: "\u5E38\u89C1\u8BCA\u65AD\u7801\u4E0E\u4FEE\u6CD5", text: ERRORS_REFERENCE };
    case "tools":
      return {
        title: "\u5DE5\u5177\u6E05\u5355\uFF08" + catalog.length + " \u4E2A\uFF09",
        text: [
          catalog.map((t) => {
            const schema = t.parameters ?? {};
            const req = Array.isArray(schema.required) ? schema.required : [];
            const props = Object.keys(schema.properties ?? {});
            const opt = props.filter((x) => !req.includes(x));
            return t.name + " [" + t.behavior + "] " + t.description + (props.length > 0 ? "\n      \u5FC5\u586B: " + (req.length > 0 ? req.join(", ") : "\uFF08\u65E0\uFF09") + " | \u53EF\u9009: " + (opt.length > 0 ? opt.join(", ") : "\uFF08\u65E0\uFF09") : "");
          }).join("\n"),
          "",
          '\u60F3\u770B\u67D0\u4E2A\u5DE5\u5177\u7684\u5B8C\u6574\u53C2\u6570\u6811\uFF08\u7C7B\u578B/\u63CF\u8FF0/\u5FC5\u586B\uFF09\uFF1Anormify_help { topic: "tool:<\u5DE5\u5177\u540D>" }\uFF0C\u4F8B\u5982 "tool:normify_module_batch"\u3002'
        ].join("\n")
      };
    case "all":
      return {
        title: "\u5168\u90E8\u53C2\u8003",
        text: [
          "=== fields ===",
          fieldReference(),
          "",
          "=== deps ===",
          DEPS_REFERENCE,
          "",
          "=== renders ===",
          RENDERS_REFERENCE,
          "",
          "=== flow ===",
          FLOW_REFERENCE,
          "",
          "=== policy ===",
          policyReference(),
          "",
          "=== errors ===",
          ERRORS_REFERENCE,
          "",
          "=== tools ===",
          topicReference("tools", catalog).text
        ].join("\n")
      };
  }
}
